function send(type,data={}){if(socket?.readyState!==WebSocket.OPEN){notify('ارتباط با سرور قطع است.');return}if(!authorized&&type!=='auth'){notify('برای مدیریت، ابتدا وارد پنل شوید.');return}socket.send(JSON.stringify({type,...data}))}
function notify(text){$('notice').textContent=text}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
function avatar(person,ring=true){const box=node('span','avatar');box.append(node('span','initial',(person?.name||'?').slice(0,1)));if(person?.avatar&&/^(https:\/\/|data:image\/(png|jpeg|webp);base64,|\/avatars\/preview-[1-8]\.svg$)/.test(person.avatar)){const img=node('img');img.src=person.avatar;img.alt=person.name;img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();box.append(img)}if(ring){const canvas=node('canvas','ring');canvas.width=180;canvas.height=180;box.append(canvas)}return box}
function flagEmoji(flag){return Array.from(flag||'').map(c=>String.fromCharCode(c.codePointAt(0)-0x1f1e6+97)).join('')}
function flag(flag){const img=node('img','flag');img.src='/flags/'+flagEmoji(flag)+'.svg';img.alt=flag;img.onerror=()=>img.replaceWith(node('span','flag',flag));return img}
function connect(){clearTimeout(reconnectTimer);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=()=>{if(token)send('auth',{token})};socket.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch{return}if(m.type==='snapshot'){lastMessage=m;serverOffset=(m.serverNow||Date.now())-Date.now();race=m.snapshot.race;if(race)render();return}if(m.type==='auth'){authorized=!!m.ok;$('operatorBar').hidden=!screen||!authorized;$('auth').hidden=authorized;$('tools').hidden=!authorized;notify(authorized?'پنل باز شد.':'کلید مدیریت معتبر نیست.');return}if(m.type==='race-join')welcome(m);if(m.type==='error'||m.type==='notice')notify(m.message);if(m.type==='race-reaction')burst(m.kind)};socket.onclose=()=>{authorized=false;$('tools').hidden=true;$('auth').hidden=false;$('liveBadge').textContent='● RECONNECTING';$('connectionStatus').textContent='ارتباط با سرور قطع شد؛ تلاش دوباره…';reconnectTimer=setTimeout(connect,2000)};socket.onerror=()=>socket.close()}
function render(){const m=lastMessage,r=race;document.body.classList.toggle('effects-off',r.settings.effects===false);$('connectionStatus').textContent=m.status;$('liveBadge').textContent=m.connected?'● LIVE CONNECTED':m.demoRunning?'● DEMO':'● READY';$('demoBanner').hidden=!m.demoRunning&&!m.manualTests;$('demoBanner').textContent=m.manualTests?'TEST MODE':'DEMO';document.body.classList.toggle('gifts-left',r.settings.railOrder==='gifts-left');$('stage').style.backgroundColor=r.settings.background;$('stage').style.setProperty('--rail-top',r.settings.railTop+'px');$('startDemo').disabled=!!m.demoRunning;$('stopDemo').disabled=!m.demoRunning;if(document.activeElement!==$('username')&&!$('username').value&&m.username)$('username').value=m.username;$('traffic').textContent='رویدادها — ورود: '+m.traffic.joins+' · لایک: '+m.traffic.likes+' · گیفت: '+m.traffic.gifts;$('roundLabel').textContent='ROUND '+r.round;$('liveTitle').textContent=r.settings.playMode==='gifts'?'Gift and Move':'Like and Move';$('totalLikes').textContent='♥ '+(m.snapshot.likes||0).toLocaleString();$('raceRule').textContent='مسیر '+r.settings.length+' متر · هر قدم '+r.settings.step+' متر · '+modeLabel();$('likeRule').textContent=r.settings.playMode==='likes'?'۱۰ لایک = ۱ قدم':'حرکت با لایک خاموش است';$('giftRule').textContent=r.settings.giftsEnabled?'هر گیفت مشخص = ۱ قدم':'گیفت کمکی خاموش است';renderModes();
 const track=$('track');track.style.setProperty('--cars',r.settings.cars);
 for(const old of [...track.children])if(Number(old.dataset.index)>=r.settings.cars)old.remove();
 for(let i=0;i<r.settings.cars;i++){let lane=track.children[i];if(!lane){lane=node('div','lane');lane.dataset.index=i;const road=node('div','road');road.append(node('div','finish-line'));const vehicle=node('div','vehicle');vehicle.innerHTML='<div class="car"><i class="window front"></i><i class="window back"></i><i class="wheel w1"></i><i class="wheel w2"></i><i class="wheel w3"></i><i class="wheel w4"></i><b></b></div>';road.append(vehicle);lane.append(road,node('div','driver'));track.append(lane)}lane.style.setProperty('--car',palette[i]);const p=r.slots[i],driver=lane.querySelector('.driver'),vehicle=lane.querySelector('.vehicle');driver.tabIndex=0;driver.setAttribute('role','button');driver.setAttribute('aria-label','CAR '+(i+1)+' SUPPORTERS');driver.onclick=()=>showSupporters(i);driver.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showSupporters(i)}};lane.classList.toggle('empty',!p);lane.classList.toggle('demo-lane',!!p?.isDemo);lane.classList.toggle('winner-lane',r.winner===i);const key=JSON.stringify([p?.id,p?.name,p?.avatar,p?.countryFlag,r.flags[i],r.giftMap[i]]);if(lane.dataset.profile!==key){lane.dataset.profile=key;driver.replaceChildren();driver.append(avatar(p),node('strong','driver-name',p?.name||'OPEN SLOT'),node('small','car-gift',giftTitle(r.giftMap[i])));const chosenFlag=racerFlag(p,i);vehicle.querySelector('.car b').replaceChildren(...(chosenFlag?[flag(chosenFlag)]:[]));let carFace=vehicle.querySelector('.car-face');if(!carFace){carFace=node('span','car-face');vehicle.querySelector('.car').append(carFace)}carFace.replaceChildren(avatar(p,false));driver.append(node('span','distance','0m'),node('small','driver-likes'));}driver.querySelector('.distance').textContent=Math.floor(p?.distance||0)+'m';driver.querySelector('.driver-likes').textContent=p?'♥ '+p.likes+' · 🎁 '+p.gifts:'AUTO JOIN';const identity=p?.id||'';if(vehicle.dataset.identity!==identity||vehicle.dataset.round!==String(r.round)){vehicle.dataset.identity=identity;vehicle.dataset.round=r.round;vehicle._position=p?.distance||0}vehicle._target=p?.distance||0;vehicle._length=r.settings.length;if(p?.lastMoveAt&&vehicle.dataset.moveAt!==String(p.lastMoveAt)){vehicle.dataset.moveAt=String(p.lastMoveAt);let gain=vehicle.querySelector('.move-badge');if(!gain){gain=node('span','move-badge');vehicle.append(gain)}gain.textContent='+'+(p.lastSteps||1);gain.classList.remove('active');void gain.offsetWidth;gain.classList.add('active');lane.classList.remove('step-flash');void lane.offsetWidth;lane.classList.add('step-flash')}}
 renderRail('likerRail',r.likers,'likes',r.settings.likerCount);renderRail('gifterRail',r.gifters,'gifts',r.settings.gifterCount);
 $('queueCount').textContent=r.queue.length;document.querySelector('.waiting').hidden=r.queue.length===0;$('waitingList').replaceChildren();for(const [i,p] of r.queue.entries()){const item=node('div','waiting-person');item.append(node('b','',String(i+1)),avatar(p,false),node('strong','',p.name));$('waitingList').append(item)}if(!r.queue.length)$('waitingList').append(node('p','','—'));
 renderDriverRoster();renderCompetition();renderRaceControls();renderSettings();renderManagement();renderDiagnostics();renderWinner();updateStatus();}
function renderRail(id,people,field,count){const list=$(id).querySelector('.rail-list'),selected=[...people].sort((a,b)=>b[field]-a[field]).slice(0,count),key=JSON.stringify([selected,count,race.settings.ring,race.settings.likerFrame,race.settings.gifterFrame,race.settings.giftStyleBasis,race.settings.tierSimple,race.settings.tierSilver,race.settings.tierGold,race.settings.tierIce,race.settings.tierFire]);if(list.dataset.key===key)return;list.dataset.key=key;list.replaceChildren();selected.forEach((p,i)=>{const card=node('div','audience-card'+(i===0?' featured':''));const face=avatar(p);face.querySelector('canvas').dataset.level=frameLevel(p,field);card.append(node('span','rank',i===0?'♛':String(i+1)),face,node('strong','',p.name),node('b','score',(field==='likes'?'♥ ':'🎁 ')+p[field].toLocaleString()));if(i===0){card.append(node('span','heartbeat',field==='likes'?'♥':'🎁'));const handle=String(p.uniqueId||'').replace(/^@/,'');if(/^[A-Za-z0-9._]{1,32}$/.test(handle)){const link=node('a','follow','Follow +');link.href='https://www.tiktok.com/@'+encodeURIComponent(handle);link.target='_blank';link.rel='noopener noreferrer';card.append(link)}}list.append(card)});if(!selected.length)list.append(node('p','empty-rail',field==='likes'?'LIKE':'GIFT'))}
function updateStatus(){if(!race)return;const r=race,remaining=Math.max(0,Math.ceil((r.startsAt-Date.now()-serverOffset)/1000));$('countdown').hidden=remaining===0||!r.settings.running||r.settings.paused||r.winner!==null;$('countdownNumber').textContent=Math.min(3,remaining);$('countryPrompt').hidden=!remaining||!r.slots.some(p=>p&&!p.isDemo&&!p.countryFlag);if(!r.settings.running){$('raceStatus').textContent='STOPPED';$('countdown').hidden=true;return}if(r.settings.paused){$('raceStatus').textContent='PAUSED';return}if(r.winner!==null){const seconds=Math.max(0,Math.ceil((r.nextGameAt-Date.now()-serverOffset)/1000));$('raceStatus').textContent=(r.slots[r.winner]?.name||'WINNER')+' WINS'+(r.settings.autoRestart?' · NEXT ROUND '+seconds+'s':'');return}$('raceStatus').textContent=''}
function showSupporters(i){const car=race?.slots[i];$('supporterTitle').textContent='CAR '+(i+1)+' SUPPORTERS'+(car?' · '+car.name:'');const list=$('supporterList');list.replaceChildren();for(const [rank,p]of [...(car?.supporters||[])].sort((a,b)=>b.gifts-a.gifts).entries()){const row=node('div','supporter-row');row.append(node('b','',rank===0?'♛':String(rank+1)),avatar(p),node('strong','',p.name),node('span','','🎁 '+p.gifts));list.append(row)}if(!list.children.length)list.append(node('p','','No supporters yet.'));$('supporters').showModal()}
$('closeSupporters').onclick=()=>$('supporters').close();
let winnerKey='';function renderWinner(){const r=race,box=$('winner'),key=r.round+':'+r.winner;box.hidden=r.winner===null;if(key===winnerKey)return;winnerKey=key;box.replaceChildren();if(r.winner!==null){if(r.settings.celebrationMusic)victoryTune();const p=r.winnerResult||r.slots[r.winner],result=r.winnerResult;box.append(node('span','trophy','🏆'),avatar(p),node('h2','',p?.name||'WINNER'),node('p','',p?.isDemo?'DEMO WINNER':'WINNER'));if(result){const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2});box.append(node('strong','winner-coins',fmt(result.winnerCoins)+' '+(result.mode==='fixed'?'GAME COINS':'COINS*')),node('p','winner-score','SCORE '+fmt(result.score)));if(result.mode==='split'){box.append(node('p','winner-breakdown','GIFTS '+fmt(result.grossCoins)+' · TIKTOK 50% '+fmt(result.platformCoins)),node('p','winner-breakdown','CREATOR '+fmt(result.creatorCoins)),node('small','winner-estimate',result.unpricedGifts?'* ESTIMATE · SOME GIFT PRICES UNKNOWN':'* ESTIMATED VALUE · NO AUTOMATIC PAYOUT'))}}burst('gift')}}
function renderSettings(){const form=$('settings');if(!form.contains(document.activeElement))for(const [k,v]of Object.entries(race.settings)){const input=form.elements.namedItem(k);if(input){if(input.type==='checkbox')input.checked=v;else input.value=v}}const key=JSON.stringify([race.settings.cars,race.flags,race.giftMap,race.giftNames]);if($('slotSettings').dataset.key!==key&&!$('slotSettings').contains(document.activeElement)){$('slotSettings').dataset.key=key;$('slotSettings').replaceChildren();for(let i=0;i<race.settings.cars;i++){const row=node('form','slot-row'),label=node('label','','موتر '+(i+1)),input=node('input');input.value=race.flags[i];input.setAttribute('aria-label','بیرق موتر '+(i+1));input.maxLength=8;const select=node('select');select.setAttribute('aria-label','گیفت موتر '+(i+1));for(const [id,title]of allGifts()){const o=node('option','',title);o.value=id;select.append(o)}select.value=race.giftMap[i];const manual=node('input');manual.placeholder='شناسهٔ دستی گیفت';manual.inputMode='numeric';manual.setAttribute('aria-label','شناسهٔ دستی گیفت موتر '+(i+1));const giftName=node('input');giftName.placeholder='نام گیفت دستی';giftName.maxLength=70;const button=node('button','','ذخیرهٔ بیرق و گیفت');row.append(label,input,select,manual,giftName,button);row.onsubmit=e=>{e.preventDefault();send('race-slot',{index:i,flag:input.value.trim(),giftId:manual.value.trim()||select.value,giftName:giftName.value.trim()})};$('slotSettings').append(row)}}const test=$('testGift');if(!test.matches(':focus')){const old=test.value;test.replaceChildren();for(const [id,title]of allGifts()){const o=node('option','',title);o.value=id;test.append(o)}if([...test.options].some(o=>o.value===old))test.value=old}}
function renderManagement(){const list=$('managePlayers'),key=JSON.stringify([...race.slots,...race.queue].map(p=>[p?.id,p?.name,p?.avatar]));if(list.dataset.key!==key&&!list.contains(document.activeElement)){list.dataset.key=key;list.replaceChildren();[...race.slots.map((p,i)=>p&&!p.isDemo?{...p,label:'موتر '+(i+1)}:null),...race.queue.map(p=>({...p,label:'انتظار'}))].filter(Boolean).forEach(p=>{const row=node('div','manage-row'),name=node('input'),photo=node('input'),save=node('button','','ذخیره نام و عکس'),remove=node('button','','خروج'),block=node('button','danger','مسدود');name.value=p.name;name.maxLength=40;name.setAttribute('aria-label','نام '+p.name);photo.type='file';photo.accept='image/png,image/jpeg,image/webp';photo.setAttribute('aria-label','عکس '+p.name);let image=p.avatar;photo.onchange=async()=>{const f=photo.files[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>5000000){notify('عکس PNG، JPEG یا WebP تا ۵ مگابایت انتخاب کنید.');return}const bitmap=await createImageBitmap(f);const c=document.createElement('canvas');c.width=c.height=100;const size=Math.min(bitmap.width,bitmap.height);c.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,100,100);image=c.toDataURL('image/jpeg',.8);bitmap.close()};save.onclick=()=>send('race-edit',{userId:p.id,name:name.value.trim(),avatar:image});remove.onclick=()=>send('race-remove',{userId:p.id});block.onclick=()=>send('remove-user',{userId:p.id});row.append(node('span','',p.label),name,photo,save,remove,block);list.append(row)})}const restore=$('restorePlayers');restore.replaceChildren();const people=new Map((race.removed||[]).map(p=>[p.id,p.name]));for(const id of lastMessage.snapshot.blockedUsers||[])if(!people.has(id))people.set(id,id);for(const [id,name]of people){const row=node('div','manage-row'),button=node('button','','رفع مسدودی / برگشت به صف');button.onclick=()=>send('race-restore',{userId:id});row.append(node('span','',name),button);restore.append(row)}}
function allGifts(){const map=new Map(gifts);for(const [id,name]of Object.entries(race?.giftNames||{}))map.set(id,name);return [...map]}
function giftTitle(id){return race?.giftNames?.[id]||gifts.find(g=>g[0]===id)?.[1]||'Gift #'+id}
function frameLevel(p,field){const s=race.settings,chosen=field==='likes'?s.likerFrame:s.gifterFrame;if(chosen&&chosen!=='auto')return chosen;if(field==='likes')return p.likes>=1000?'gold':p.likes>100?'glow':'simple';const value=s.giftStyleBasis==='coins'?p.lastGiftCoins:p.lastGiftCount;if(value==null)return 'glow';return value>=s.tierFire?'fire':value>=s.tierIce?'ice':value>=s.tierGold?'gold':value>=s.tierSilver?'silver':value>=s.tierSimple?'simple':'glow'}
function renderDiagnostics(){const c=lastMessage.connection||{};$('diagnostics').textContent='Connection: '+(c.status||'disconnected')+'\nAccount: '+(lastMessage.username||'—')+'\nRetry: '+(c.retryAttempt||0)+(c.retryAt?' · '+Math.max(0,Math.ceil((c.retryAt-Date.now())/1000))+'s':'')+'\n'+(c.diagnostics||[]).map(d=>[d.reason,d.httpStatus,d.route].filter(Boolean).join(' · ')).join('\n');$('giftEvents').textContent=(race.events||[]).map(e=>new Date(e.at).toLocaleTimeString()+' · '+(e.name||'Viewer')+' · '+(e.kind==='gift'?'Gift #'+e.giftId+' × '+e.count+' · '+e.reason:'JOIN')).join('\n')||'هنوز رویدادی ثبت نشده است.'}
function welcome(m){const toast=node('div','join-toast');toast.append(avatar({name:m.name,avatar:m.avatar},false),node('span','',m.name+' joined the LIVE'));$('joinToasts').append(toast);setTimeout(()=>toast.remove(),5000);while($('joinToasts').children.length>4)$('joinToasts').firstElementChild.remove();if(race?.settings.welcomeVoice&&race.settings.sound&&'speechSynthesis'in window){const speech=new SpeechSynthesisUtterance('Welcome to the live race');speech.volume=race.settings.volume/100;window.speechSynthesis.speak(speech)}}
let audio;document.addEventListener('pointerdown',()=>{try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume()}catch{}},{once:true});
function burst(kind){if(race?.settings.sound&&audio?.state==='running'){const tone=audio.createOscillator(),gain=audio.createGain();tone.connect(gain);gain.connect(audio.destination);tone.frequency.value=kind==='like'?660:880;gain.gain.setValueAtTime(Math.max(.001,race.settings.volume/100*.12),audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);tone.start();tone.stop(audio.currentTime+.2)}if(race?.settings.effects===false)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=node('span','reaction',kind==='like'?'♥':'🎁');$(kind==='like'?'likerRail':'gifterRail').append(el);setTimeout(()=>el.remove(),1400)}
function animate(time){animationFrame=requestAnimationFrame(animate);if(time-lastTick<33)return;const dt=Math.min(100,time-lastTick||33);lastTick=time;document.querySelectorAll('.vehicle').forEach(v=>{const target=v._target||0,current=matchMedia('(prefers-reduced-motion: reduce)').matches?target:v._position||0;v._position=Math.abs(target-current)<.02?target:current+(target-current)*Math.min(1,dt/220);const fraction=Math.max(0,Math.min(1,v._position/(v._length||1000)));const roadHeight=v.parentElement.clientHeight,start=roadHeight*.04,end=Math.max(start,roadHeight*.93-v.offsetHeight);v.style.bottom=(start+fraction*(end-start))+'px';v.classList.toggle('moving',Math.abs(target-current)>.05)});if(ringDraw&&race){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const canvas of document.querySelectorAll('canvas.ring')){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,180,180);const level=canvas.dataset.level||race.settings.ring;if(level==='none')continue;ringDraw(ctx,90,90,108,level,reduced||race.settings.effects===false?0:time,{speed:race.settings.ringSpeed/100,intensity:race.settings.ringIntensity/100,ornaments:race.settings.ornaments})}}}
$('panelToggle').onclick=()=>{$('panel').hidden=!$('panel').hidden};$('closePanel').onclick=()=>{$('panel').hidden=true};$('unlock').onclick=()=>{token=$('adminKey').value.trim();sessionStorage.setItem('race-admin',token);send('auth',{token});$('adminKey').value=''};$('connect').onclick=()=>send('connect',{username:$('username').value.trim()});$('disconnect').onclick=()=>send('disconnect');$('startDemo').onclick=()=>send('demo-start');$('stopDemo').onclick=()=>send('demo-stop');$('newRound').onclick=()=>send('race-new');$('settings').onsubmit=e=>{e.preventDefault();const settings={};for(const el of e.target.elements)if(el.name)settings[el.name]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'||el.type==='color'||el.type==='hidden'?el.value:Number(el.value);send('race-settings',{settings})};document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>send('race-demo',{action:b.dataset.test,userId:$('testId').value,name:$('testName').value,count:Number($('testCount').value),giftId:$('testGift').value,content:$('testCountry').value.trim()}));
function tone(hz,delay=0){if(!audio||audio.state!=='running')return;const osc=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+delay;osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=hz;gain.gain.setValueAtTime(Math.max(.001,(race?.settings.volume||20)/100*.1),at);gain.gain.exponentialRampToValueAtTime(.001,at+.2);osc.start(at);osc.stop(at+.22)}
function victoryTune(){if(!race?.settings.sound)return;[523,659,784,1046].forEach((hz,i)=>tone(hz,i*.15))}
for(const id of ['likerFrame','gifterFrame'])for(const [value,label]of Object.entries({auto:'خودکار بر اساس امتیاز',none:'بدون قاب',simple:'ساده',glow:'نورانی',silver:'نقره‌ای',gold:'طلایی',ice:'یخی / الماسی',fire:'آتش و اژدها'})){const option=node('option','',label);option.value=value;$(id).append(option)}
$('screenURL').value=location.origin+'/screen';$('copyScreen').onclick=async()=>{try{await navigator.clipboard.writeText($('screenURL').value);notify('لینک نمایش کپی شد.')}catch{$('screenURL').select();notify('لینک را کپی کنید.')}};const soundTest=()=>{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().then(()=>{tone(660);tone(880,.2)})};$('testSound').onclick=soundTest;$('screenSound').onclick=soundTest;$('screenTestSound').onclick=soundTest;const pause=()=>send('race-settings',{settings:{paused:!race.settings.paused}});$('pauseRace').onclick=pause;$('screenPause').onclick=pause;$('screenNext').onclick=()=>send('race-new');$('clearTests').onclick=()=>send('race-clear-tests');$('addPlayer').onclick=()=>send('race-add',{userId:$('manualId').value.trim(),name:$('manualName').value.trim()});
import('/rings.js').then(m=>{ringDraw=m.drawRing}).catch(()=>notify('بارگذاری حلقه‌ها ممکن نشد.'));setInterval(updateStatus,100);requestAnimationFrame(animate);connect();

function modeLabel(){return race.settings.playMode==='gifts'?'فقط گیفت':race.settings.giftsEnabled?'لایک + گیفت کمکی':'فقط لایک'}
function renderModes(){const giftMode=race.settings.playMode==='gifts';$('playMode').value=giftMode?'gifts':'likes';$('modeLikes').setAttribute('aria-pressed',String(!giftMode));$('modeGifts').setAttribute('aria-pressed',String(giftMode));$('giftAssist').checked=race.settings.giftsEnabled;$('giftAssist').disabled=giftMode;$('giftAssistLabel').textContent=giftMode?'حرکت با گیفت در این حالت فعال است':'گیفت کمکی در بازی با لایک';$('modeDescription').textContent=giftMode?'حالت گیفت: فقط گیفت مشخص موتر، آن را حرکت می‌دهد؛ لایک حرکت ایجاد نمی‌کند.':race.settings.giftsEnabled?'حالت لایک + گیفت: هر ۱۰ لایک برای موتر خودتان یک قدم؛ هر گیفت مشخص برای موتر همان خط یک قدم.':'حالت لایک: هر ۱۰ لایک برای موتر خودتان یک قدم. برای حرکت با گیفت هم، گزینهٔ گیفت کمکی را روشن کنید.'}
$('modeLikes').onclick=()=>send('race-settings',{settings:{playMode:'likes'}});$('modeGifts').onclick=()=>send('race-settings',{settings:{playMode:'gifts'}});$('giftAssist').onchange=()=>send('race-settings',{settings:{giftsEnabled:$('giftAssist').checked}});

function renderDriverRoster(){const root=$('driverRoster');while(root.children.length>race.settings.cars)root.lastElementChild.remove();for(let i=0;i<race.settings.cars;i++){const p=race.slots[i];let card=root.children[i];if(!card){card=node('button','roster-card');card.type='button';card.onclick=()=>showSupporters(i);card.style.setProperty('--car',palette[i]);root.append(card)}const signature=JSON.stringify([p?.id,p?.name,p?.avatar,p?.isDemo,p?.countryFlag,race.flags[i],race.giftMap[i],race.giftNames]);if(card.dataset.profile!==signature){card.dataset.profile=signature;card.replaceChildren(avatar(p),node('span','roster-number',String(i+1)));const copy=node('span','roster-copy');copy.append(node('strong','roster-name',p?.name||'OPEN SLOT'),node('small','roster-gift',giftTitle(race.giftMap[i])));const chosenFlag=racerFlag(p,i);if(chosenFlag)copy.querySelector('.roster-name').prepend(flag(chosenFlag));card.append(copy,node('span','roster-distance'));card.classList.toggle('is-demo',!!p?.isDemo);if(p?.isDemo)copy.append(node('small','demo-label','DEMO'))}card.querySelector('.roster-distance').textContent=Math.floor(p?.distance||0)+'m';card.setAttribute('aria-label','موتر '+(i+1)+' · '+(p?.name||'OPEN SLOT'))}}

function racerFlag(person,index){return person?.isDemo?race.flags[index]:person?.countryFlag||''}

let lastRaceLeader=null,lastLeaderRound=0;
function renderCompetition(){const rows=race.slots.slice(0,race.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p).sort((a,b)=>b.p.distance-a.p.distance||a.i-b.i),top=rows[0];if(lastLeaderRound!==race.round){lastRaceLeader=null;lastLeaderRound=race.round}for(let position=0;position<rows.length;position++){const {p,i}=rows[position],card=$('driverRoster').children[i],lane=$('track').children[i];if(!card||!lane)continue;let badge=card.querySelector('.roster-position');if(!badge){badge=node('span','roster-position');card.append(badge)}badge.textContent='P'+(position+1);const isLead=position===0&&p.distance>0;card.classList.toggle('race-leader',isLead);lane.classList.toggle('race-leader',isLead);card.style.setProperty('--progress',Math.min(100,p.distance/race.settings.length*100)+'%')}if(top?.p.distance>0){if(lastRaceLeader!==null&&lastRaceLeader!==top.p.id&&race.settings.effects&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$('track').classList.remove('overtake');void $('track').offsetWidth;$('track').classList.add('overtake');setTimeout(()=>$('track').classList.remove('overtake'),900)}lastRaceLeader=top.p.id}document.body.classList.toggle('final-sprint',!!top&&top.p.distance/race.settings.length>=.8)}

for(const [id,action]of [['raceStart','start'],['racePause','pause'],['raceResume','resume'],['raceStop','stop']])$(id).onclick=()=>send('race-control',{action});
function renderRaceControls(){const s=race.settings;const state=!s.running?'متوقف کامل':s.paused?'توقف موقت':Date.now()+serverOffset<race.startsAt?'شمارش معکوس':'در حال مسابقه';$('raceControlStatus').textContent='وضعیت: '+state;$('racePause').disabled=!s.running||s.paused;$('raceResume').disabled=!s.running||!s.paused;$('raceStop').disabled=!s.running;}
